// Astro config for a client site. All content comes from site.config.json
// (generated by `uv run python tools/build_site_config.py --client <slug>`). Do not hand-edit that file.
import { defineConfig } from 'astro/config';
import sitemap from '@astrojs/sitemap';
import { readFileSync } from 'node:fs';

const config = JSON.parse(readFileSync(new URL('./site.config.json', import.meta.url), 'utf-8'));

export default defineConfig({
  site: config.site_url,
  trailingSlash: 'always',
  build: { format: 'directory' },
  integrations: [sitemap({ filter: (page) => !page.includes('/404') })],
});
